// TH18 v1.00a Stage 4 MainSub00 / Cir00; source st04.ecl.txt:852-863 and 6-67.
// Source t0 = wave start; target t0 is shifted by the 120-frame opening buffer.
const TIME_LIMIT: int = 1620;      // segment timer from phase_begin (buffer + source window)
const SOURCE_LIMIT: int = 1500;    // local estimate: full 23-spawn schedule + fire cycle + tail
const OPENING_BUFFER: int = 120;
const TH18_RICE: int = 480;        // copied from engine/touhou-bullets.ecl

// Cir00_at 27-67: wait20, et0 (type8/color2), mode0 aimed, etCount(1,1),
// per-rank count/speed/interval.  Every etOn reads a fresh RANDF2 angle offset.
async sub cir00_at(end_frame: int) {
    var rank: int = global(GVAR_RANK);
    var shots: int = 2;            // diffI($A,2,16,50,100)
    var gap: int = 60;             // wait branch E60/N10/H8/LO8
    var speed: fx = 1.2fx;         // etSpeed: M=1 so only the first (top-of-stack) value is used
    if rank == 1 { shots = 16; gap = 10; speed = 1.8fx; }
    else if rank == 2 { shots = 50; gap = 8; speed = 1.8fx; }
    else if rank >= 3 { shots = 100; gap = 8; speed = 2.3fx; }

    var retreat: fx = 4fx * speed; // ANIM type2 entry: position -= 4*velocity
    wait(20);
    for k in 0..shots {
        if $frame >= end_frame { return; }
        // etAngle(0, RANDF2*pi/4, 0); mode0/N=1 gives aim + alpha.
        var u: fx = (rand(65536)-32768) as fx / 32768;
        var off: int = (u * 8192fx) as int; // pi/4 in BAM
        var a: angle = aim_player() + (off as angle);
        _ = fire(TH18_RICE, 2, $self_x - retreat*cos(a), $self_y - retreat*sin(a), speed, a, none, none);
        wait(gap);
    }
}

// Cir00 6-26: boxes, ABS velocity 1.4 at 90deg+RANDF2*20deg, REL ellipse
// theta0=0, omega=2deg, r=10, d=0, beta=ABS_ANGLE snapshot, scale=0.
async sub cir00_main(end_frame: int) {
    set_invuln(65535);
    set_hurtbox(14fx); // source setHurtbox(28,28)
    set_hitbox(8fx);   // source setHitbox(16,16); body collision kept
    var u: fx = (rand(65536)-32768) as fx / 32768;
    var off: int = (u * 3641fx) as int; // 20deg in BAM
    var beta: angle = 90deg + (off as angle);
    var sb: fx = sin(beta);
    var cb: fx = cos(beta);
    var px: fx = $self_x;
    var py: fx = $self_y;
    var theta: angle = 0deg;
    var e: fx = 10fx * sin(theta-beta);
    // moveEllipseRel applies the REL layer immediately at set time.
    move_to(0, px - e*sb, py + e*cb, EASE_LINEAR);
    spawn cir00_at(end_frame);
    loop {
        if $frame >= end_frame { return; }
        px = px + 1.4fx*cb;
        py = py + 1.4fx*sb;
        theta = theta + 2deg;
        if theta >= 360deg { theta = theta - 360deg; }
        e = 10fx * sin(theta-beta);
        // target position = ABS layer + REL ellipse layer, both integrated here.
        move_to(0, px - e*sb, py + e*cb, EASE_LINEAR);
        wait(1);
    }
}

// MainSub00 852-863: 23 planned Cir00 creations every 15 frames.
async sub wave_pattern() {
    wait(OPENING_BUFFER);
    var start: int = $frame;
    var end: int = start + SOURCE_LIMIT;
    for i in 0..23 {
        var u: fx = (rand(65536)-32768) as fx / 32768;
        var x: fx = u * 128fx; // RANDF2 * _f(128), relative to control enemy at (0,0)
        _ = spawn_enemy(x, -32fx, 320, 0, 0, 0, cir00_main(end));
        wait(15);
    }
}

// Control enemy shell: (0,0), no body collision, invulnerable phase owner.
async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
